// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.vision.memoryimport android.security.keystore.KeyGenParameterSpecimport android.security.keystore.KeyPropertiesimport java.security.KeyStoreimport java.security.SecureRandomimport javax.crypto.Cipherimport javax.crypto.KeyGeneratorimport javax.crypto.SecretKeyimport javax.crypto.spec.GCMParameterSpecimport timber.log.Timber/** * NOUS — Visual Episodic Memory (Module 6 v4 — Step 6.6, CRITICAL). * * Implements the **Spatial-Temporal Ring Buffer** — a 10-second rolling visual * memory that lets NOUS answer "what did I just see?" queries, per strategy v3 * §"Upgrade 2: Spatial-Temporal Ring Buffer" + v4 §"Critical Engineering Fix 3: * LMK Survival". * * ## Why this matters * * Without episodic memory, vision is reactive — NOUS only knows what's in front * of the camera RIGHT NOW. With the ring buffer: * * ``` * User: "Abhi jo table par receipt padi thi, total kya tha?" *   ↓ * Brain retrieves from ring buffer → finds receipt frame from 30 seconds ago *   ↓ * NOUS: "₹309.75, Big Bazaar receipt from 30 seconds ago." * ``` * * ## Architecture * * ``` * Camera frames (30 FPS) → Motion Gating filter → ~3 FPS saved frames *   ↓ * Each saved frame → Omni-SLM visual encoder → 256-dim embedding *   ↓ * Ring buffer: 30 embeddings × 10 seconds = 300 vectors (~300 KB RAM) *   ↓ * On user query: vector similarity search over ring buffer *   ↓ * Top-K frames retrieved → Omni-SLM answers * ``` * * ## Privacy (per strategy v4 §"Privacy & Security") * *  - **RAM-only by default.** Ring buffer NEVER touches disk during normal operation. *  - **Encrypted serialization for LMK survival.** When the camera UI minimizes *    (v4 §"Critical Engineering Fix 3"), the buffer is serialized to an encrypted *    local cache file (`episodic_cache.enc`) so it survives Android's Low Memory *    Killer. Restored when camera reopens. *  - **No raw frames stored.** Only 256-dim embeddings (cryptographically useless *    without the Omni-SLM model + key). *  - **Cleared on app close, screen lock, or user command** ("forget what you saw"). *  - **User can disable** in Settings → Privacy → Visual Episodic Memory. *  - **Encryption:** AES-256-GCM with key stored in AndroidKeystore (hardware-backed). * * ## LMK Survival Protocol (v4 §"Critical Engineering Fix 3") * * On 3 GB RAM devices, Android's Low Memory Killer can evict NOUS when WhatsApp/ * YouTube open. To preserve episodic memory: * * ``` * T+0ms: Camera UI minimizes (ActivityLifecycleCallback.onStop) *   ↓ * T+50ms: Serialize 300 embeddings (~300 KB) → AES-256-GCM encrypt → write to episodic_cache.enc *   ↓ * T+500ms: Clear ring buffer from RAM * * Re-activation (user returns to camera): *   ↓ * T+0ms: ActivityLifecycleCallback.onStart *   ↓ * T+20ms: Read episodic_cache.enc → AES-256-GCM decrypt → restore 300 embeddings *   ↓ * T+100ms: Ring buffer restored — user can query "what did I just see?" * ``` * * ## Testability * * The encryption layer is abstracted via [EpisodicMemoryEncryptor] interface. * Production: [AesEpisodicMemoryEncryptor] uses AndroidKeystore AES-256-GCM. * Tests: `FakeEpisodicMemoryEncryptor` in `src/test/kotlin/` returns plaintext * (no crypto in unit tests — AndroidKeystore isn't available on JVM). * * @see <a href="docs/strategy/module-6-vision-strategy-v4.md">§Upgrade 2: Spatial-Temporal Ring Buffer</a> */class VisualEpisodicMemory(    private val maxFrames: Int = DEFAULT_MAX_FRAMES,    private val maxAgeMs: Long = DEFAULT_MAX_AGE_MS,    private val encryptor: EpisodicMemoryEncryptor = AesEpisodicMemoryEncryptor(),    private val clock: () -> Long = System::currentTimeMillis,) {    /** Ring buffer of episodic frames (oldest first). */    private val buffer = ArrayDeque<EpisodicFrame>()    /** True if episodic memory is enabled (user can disable in Settings). */    @Volatile    private var enabled: Boolean = true    /** Total frames ever added (for stats). */    @Volatile    private var totalFramesAdded: Int = 0    /** Total queries answered (for stats). */    @Volatile    private var totalQueriesAnswered: Int = 0    /**     * Add a new frame to the ring buffer.     *     * @param embedding 256-dim visual embedding (from Omni-SLM visual encoder).     * @param timestampMs when the frame was captured.     * @param caption optional caption (e.g., "a receipt on a table").     * @param detectedObjects optional list of detected object labels.     * @param metadata optional metadata (e.g., OCR text snippet, document type).     */    @Synchronized    fun addFrame(        embedding: FloatArray,        timestampMs: Long = clock(),        caption: String? = null,        detectedObjects: List<String> = emptyList(),        metadata: Map<String, String> = emptyMap(),    ) {        if (!enabled) return        require(embedding.size == EMBEDDING_DIM) {            "Embedding must be $EMBEDDING_DIM-dim, got ${embedding.size}"        }        val frame = EpisodicFrame(            id = totalFramesAdded++.toLong(),            timestampMs = timestampMs,            embedding = embedding.copyOf(),            caption = caption,            detectedObjects = detectedObjects,            metadata = metadata,        )        buffer.addLast(frame)        // Evict oldest if over capacity.        while (buffer.size > maxFrames) {            buffer.removeFirst()        }        // Evict expired frames (older than maxAgeMs).        evictExpired(timestampMs)        Timber.tag(TAG).v("Added frame ${frame.id} (buffer=${buffer.size}/${maxFrames}).")    }    /**     * Query the ring buffer for frames matching [queryEmbedding].     *     * Uses cosine similarity to find the top-K most similar frames.     *     * @param queryEmbedding 256-dim query embedding (from Omni-SLM text encoder).     * @param topK number of results to return (default 3).     * @param maxAgeMs only consider frames newer than this (default: full buffer).     * @return list of (frame, similarity) pairs, sorted by similarity descending.     */    @Synchronized    fun query(        queryEmbedding: FloatArray,        topK: Int = 3,        maxAgeMs: Long = Long.MAX_VALUE,    ): List<EpisodicQueryResult> {        if (!enabled || buffer.isEmpty()) {            return emptyList()        }        require(queryEmbedding.size == EMBEDDING_DIM) {            "Query embedding must be $EMBEDDING_DIM-dim, got ${queryEmbedding.size}"        }        val now = clock()        val minTimestamp = now - maxAgeMs        val results = buffer            .filter { it.timestampMs >= minTimestamp }            .map { frame ->                val similarity = cosineSimilarity(queryEmbedding, frame.embedding)                EpisodicQueryResult(                    frame = frame,                    similarity = similarity,                    ageMs = now - frame.timestampMs,                )            }            .sortedByDescending { it.similarity }            .take(topK)        totalQueriesAnswered++        Timber.tag(TAG).d("Query returned ${results.size} frames (top similarity=${results.firstOrNull()?.similarity ?: 0f}).")        return results    }    /**     * Get the most recent N frames (for "what did I just see?" queries).     *     * @param count number of recent frames to return.     * @return list of frames, most recent first.     */    @Synchronized    fun recentFrames(count: Int = 5): List<EpisodicFrame> {        return buffer.toList().takeLast(count).reversed()    }    /**     * Find frames containing a specific detected object.     *     * @param objectLabel the object label to search for (e.g., "person", "receipt").     * @param topK max results.     * @return list of matching frames, most recent first.     */    @Synchronized    fun findByObject(objectLabel: String, topK: Int = 5): List<EpisodicFrame> {        return buffer            .filter { frame -> frame.detectedObjects.any { it.equals(objectLabel, ignoreCase = true) } }            .takeLast(topK)            .reversed()    }    /**     * Find frames containing a caption keyword.     *     * @param keyword the keyword to search in captions.     * @param topK max results.     * @return list of matching frames, most recent first.     */    @Synchronized    fun findByCaptionKeyword(keyword: String, topK: Int = 5): List<EpisodicFrame> {        return buffer            .filter { frame -> frame.caption?.contains(keyword, ignoreCase = true) == true }            .takeLast(topK)            .reversed()    }    /**     * Serialize the ring buffer to an encrypted byte array (for LMK survival).     *     * Called when the camera UI minimizes. The encrypted bytes are written to     * `episodic_cache.enc` by the caller.     *     * @return encrypted serialization of the ring buffer.     */    @Synchronized    fun serializeEncrypted(): ByteArray {        val plaintext = serialize()        val encrypted = encryptor.encrypt(plaintext)        Timber.tag(TAG).d("Serialized ${buffer.size} frames (${plaintext.size} bytes → ${encrypted.size} encrypted).")        return encrypted    }    /**     * Deserialize an encrypted byte array back into the ring buffer (LMK recovery).     *     * Called when the camera UI reopens. Replaces the current buffer contents.     *     * @param encrypted the encrypted serialization.     * @return true if deserialization succeeded.     */    @Synchronized    fun deserializeEncrypted(encrypted: ByteArray): Boolean {        val plaintext = try {            encryptor.decrypt(encrypted)        } catch (t: Throwable) {            Timber.tag(TAG).e("Failed to decrypt episodic memory — clearing buffer.", t)            buffer.clear()            return false        }        val frames = try {            deserialize(plaintext)        } catch (t: Throwable) {            Timber.tag(TAG).e("Failed to deserialize episodic memory — clearing buffer.", t)            buffer.clear()            return false        }        buffer.clear()        buffer.addAll(frames)        Timber.tag(TAG).i("Restored ${buffer.size} frames from encrypted cache.")        return true    }    /** Clear the entire ring buffer. */    @Synchronized    fun clear() {        val count = buffer.size        buffer.clear()        Timber.tag(TAG).i("Cleared $count frames from episodic memory.")    }    /** Enable episodic memory. */    fun enable() {        enabled = true        Timber.tag(TAG).i("Episodic memory enabled.")    }    /** Disable episodic memory + clear buffer. */    @Synchronized    fun disable() {        enabled = false        clear()        Timber.tag(TAG).i("Episodic memory disabled + cleared.")    }    /** True if episodic memory is enabled. */    fun isEnabled(): Boolean = enabled    /** Current buffer size. */    @Synchronized    fun size(): Int = buffer.size    /** Get stats (for Settings UI). */    fun stats(): EpisodicMemoryStats = EpisodicMemoryStats(        currentFrameCount = synchronized(buffer) { buffer.size },        maxFrames = maxFrames,        totalFramesAdded = totalFramesAdded,        totalQueriesAnswered = totalQueriesAnswered,        enabled = enabled,        oldestFrameAgeMs = synchronized(buffer) {            val oldest = buffer.firstOrNull()            if (oldest != null) clock() - oldest.timestampMs else 0L        },    )    // ─── Internal helpers ─────────────────────────────────────────────────    private fun evictExpired(now: Long) {        val minTimestamp = now - maxAgeMs        while (buffer.isNotEmpty() && buffer.first().timestampMs < minTimestamp) {            buffer.removeFirst()        }    }    /** Compute cosine similarity between two vectors. */    internal fun cosineSimilarity(a: FloatArray, b: FloatArray): Float {        require(a.size == b.size) { "Vectors must have same dimension" }        var dotProduct = 0.0        var normA = 0.0        var normB = 0.0        for (i in a.indices) {            dotProduct += a[i] * b[i]            normA += a[i] * a[i]            normB += b[i] * b[i]        }        val denominator = kotlin.math.sqrt(normA) * kotlin.math.sqrt(normB)        return if (denominator > 0) (dotProduct / denominator).toFloat() else 0f    }    /** Serialize buffer to plaintext bytes. */    private fun serialize(): ByteArray {        // Format: [frameCount:Int][frame1][frame2]...        // Each frame: [id:Long][timestampMs:Long][embedding:256×Float][captionLen:Int][caption:UTF8][objectsCount:Int][objects...][metadataCount:Int][metadata...]        val stream = java.io.ByteArrayOutputStream()        val out = java.io.DataOutputStream(stream)        out.writeInt(buffer.size)        for (frame in buffer) {            out.writeLong(frame.id)            out.writeLong(frame.timestampMs)            for (i in 0 until EMBEDDING_DIM) {                out.writeFloat(frame.embedding[i])            }            out.writeUTF(frame.caption ?: "")            out.writeInt(frame.detectedObjects.size)            for (obj in frame.detectedObjects) {                out.writeUTF(obj)            }            out.writeInt(frame.metadata.size)            for ((key, value) in frame.metadata) {                out.writeUTF(key)                out.writeUTF(value)            }        }        return stream.toByteArray()    }    /** Deserialize plaintext bytes back to frames. */    private fun deserialize(bytes: ByteArray): List<EpisodicFrame> {        val stream = java.io.ByteArrayInputStream(bytes)        val input = java.io.DataInputStream(stream)        val frameCount = input.readInt()        val frames = mutableListOf<EpisodicFrame>()        for (i in 0 until frameCount) {            val id = input.readLong()            val timestampMs = input.readLong()            val embedding = FloatArray(EMBEDDING_DIM) { input.readFloat() }            val caption = input.readUTF().takeIf { it.isNotEmpty() }            val objectsCount = input.readInt()            val objects = (0 until objectsCount).map { input.readUTF() }            val metadataCount = input.readInt()            val metadata = (0 until metadataCount).associate { input.readUTF() to input.readUTF() }            frames.add(EpisodicFrame(id, timestampMs, embedding, caption, objects, metadata))        }        return frames    }    private companion object {        private const val TAG = "EpisodicMemory"        /**         * Embedding dimension. Must match [com.roshan.persona.vision.core.OmniSlmRuntime.embed]'s         * output (384-dim MiniLM-L6). Was previously 256 — would crash with         * `require(embedding.size == EMBEDDING_DIM)` on every addToMemory() call         * since OmniSlmRuntime returns 384 floats. Audit Task ID: audit-m6-vision P0.         */        private const val EMBEDDING_DIM = 384        private const val DEFAULT_MAX_FRAMES = 30  // 30 frames × 3 FPS = 10 seconds        private const val DEFAULT_MAX_AGE_MS = 10_000L  // 10 seconds    }}// ──────────────────────────────────────────────────────────────────────────/** One frame in the episodic memory ring buffer. */data class EpisodicFrame(    val id: Long,    val timestampMs: Long,    val embedding: FloatArray,    val caption: String?,    val detectedObjects: List<String>,    val metadata: Map<String, String>,) {    /** Age of this frame in milliseconds (relative to "now"). */    fun ageMs(nowMs: Long): Long = nowMs - timestampMs    /** True if this frame is older than [maxAgeMs]. */    fun isExpired(nowMs: Long, maxAgeMs: Long): Boolean = ageMs(nowMs) > maxAgeMs    override fun equals(other: Any?): Boolean {        if (this === other) return true        if (other !is EpisodicFrame) return false        return id == other.id && timestampMs == other.timestampMs &&               caption == other.caption &&               detectedObjects == other.detectedObjects &&               metadata == other.metadata &&               embedding.contentEquals(other.embedding)    }    override fun hashCode(): Int {        var result = id.hashCode()        result = 31 * result + timestampMs.hashCode()        result = 31 * result + embedding.contentHashCode()        result = 31 * result + (caption?.hashCode() ?: 0)        result = 31 * result + detectedObjects.hashCode()        result = 31 * result + metadata.hashCode()        return result    }}/** Result of an episodic memory query. */data class EpisodicQueryResult(    val frame: EpisodicFrame,    val similarity: Float,  // 0.0-1.0 (cosine similarity)    val ageMs: Long,        // how long ago this frame was captured) {    /** True if this is a strong match (similarity ≥ 0.75). */    val isStrongMatch: Boolean get() = similarity >= 0.75f    /** Human-readable age (e.g., "30 seconds ago"). */    val ageDescription: String        get() = when (ageMs) {            in 0..1000 -> "just now"            in 1000..60_000 -> "${ageMs / 1000} seconds ago"            in 60_000..3_600_000 -> "${ageMs / 60_000} minutes ago"            else -> "${ageMs / 3_600_000} hours ago"        }}/** Stats for Settings UI. */data class EpisodicMemoryStats(    val currentFrameCount: Int,    val maxFrames: Int,    val totalFramesAdded: Int,    val totalQueriesAnswered: Int,    val enabled: Boolean,    val oldestFrameAgeMs: Long,) {    /** True if the buffer is at capacity. */    val isFull: Boolean get() = currentFrameCount >= maxFrames    /** Memory usage estimate (30 frames × 384-dim × 4 bytes ≈ 46 KB). */    val estimatedMemoryBytes: Long        get() = currentFrameCount.toLong() * 384 * 4}// ──────────────────────────────────────────────────────────────────────────/** * Encryptor interface for episodic memory serialization. * * Production: [AesEpisodicMemoryEncryptor] uses AndroidKeystore AES-256-GCM * (hardware-backed on devices with TEE/StrongBox). * Tests: `FakeEpisodicMemoryEncryptor` in `src/test/kotlin/` returns plaintext * (AndroidKeystore is not available in JVM unit tests). */interface EpisodicMemoryEncryptor {    /** Encrypt [plaintext] → ciphertext. */    fun encrypt(plaintext: ByteArray): ByteArray    /** Decrypt [ciphertext] → plaintext. */    fun decrypt(ciphertext: ByteArray): ByteArray}/** * AES-256-GCM encryptor for episodic memory, backed by AndroidKeystore. * * ## Key management * * The 256-bit AES key is generated ONCE per device via [KeyGenerator] using * the `"AndroidKeyStore"` provider. The key: *   - Lives in the device's hardware-backed keystore (TEE or StrongBox on *     supported devices — never leaves secure hardware). *   - Is bound to NOUS's app signing key (cannot be extracted by another app). *   - Persists across app restarts and device reboots. *   - Is invalidated if the user changes their lock screen credential AND *     `setUserAuthenticationRequired(false)` is configured (we set false so *     the key survives lock screen changes — LMK recovery must work without *     a user prompt). * * ## Encryption scheme * *  - AES-256-GCM (authenticated encryption — tamper-proof). *  - 12-byte IV (GCM standard) — randomly generated per encryption via *    [SecureRandom], prepended to ciphertext. *  - 128-bit authentication tag (GCM default). * * ## Security guarantees * *  - Even if `episodic_cache.enc` is stolen off the device, it's useless *    without the hardware-protected key. *  - Tampering with the ciphertext (flipping bits) causes `decrypt` to throw *    `AEADBadTagException` — the tampered cache is discarded and the ring *    buffer is cleared (no corrupted state loaded). * * ## Why not just derive a key from a hardcoded secret (the old approach)? * * The previous v4 implementation used * `SHA-256("nous-episodic-memory-default-key-v4")` — a hardcoded string * baked into the APK. Anyone who decompiles the APK gets the key. AndroidKeystore * keeps the key in hardware; even with root, extracting it requires breaking * the TEE (effectively impossible on modern devices). */class AesEpisodicMemoryEncryptor : EpisodicMemoryEncryptor {    private val secretKey: SecretKey by lazy { getOrCreateKey() }    private val secureRandom = SecureRandom()    override fun encrypt(plaintext: ByteArray): ByteArray {        val iv = ByteArray(GCM_IV_BYTES).also { secureRandom.nextBytes(it) }        val cipher = Cipher.getInstance(GCM_TRANSFORM)        cipher.init(Cipher.ENCRYPT_MODE, secretKey, GCMParameterSpec(GCM_TAG_BITS, iv))        val encrypted = cipher.doFinal(plaintext)        // Prepend IV to ciphertext so decrypt can recover it.        return iv + encrypted    }    override fun decrypt(ciphertext: ByteArray): ByteArray {        require(ciphertext.size > GCM_IV_BYTES) {            "Ciphertext too short (must include $GCM_IV_BYTES-byte IV)"        }        val iv = ciphertext.copyOfRange(0, GCM_IV_BYTES)        val encrypted = ciphertext.copyOfRange(GCM_IV_BYTES, ciphertext.size)        val cipher = Cipher.getInstance(GCM_TRANSFORM)        cipher.init(Cipher.DECRYPT_MODE, secretKey, GCMParameterSpec(GCM_TAG_BITS, iv))        return cipher.doFinal(encrypted)    }    /**     * Load the AES-256 key from AndroidKeystore, or generate it on first use.     *     * The key is generated with [KeyGenParameterSpec] configured for:     *  - BLOCK_MODE_GCM + ENCRYPTION_PADDING_NONE (authenticated encryption).     *  - 256-bit key size.     *  - No user authentication requirement (so LMK recovery works without     *    prompting the user).     */    private fun getOrCreateKey(): SecretKey {        val keyStore = KeyStore.getInstance(ANDROID_KEYSTORE).apply { load(null) }        if (keyStore.containsAlias(KEY_ALIAS)) {            // Safe cast: getEntry can return null if alias was deleted between            // containsAlias and getEntry (race). It can also return a non-SecretKeyEntry            // if the alias was created by a different key type. Delete + regenerate            // in either case to avoid ClassCastException crashes.            val entry = keyStore.getEntry(KEY_ALIAS, null)            val secretEntry = entry as? KeyStore.SecretKeyEntry            if (secretEntry != null) {                return secretEntry.secretKey            }            // Entry is null or wrong type — delete and regenerate.            try { keyStore.deleteEntry(KEY_ALIAS) } catch (e: Throwable) { Timber.tag("NOUS.Vision").w(e, "Failed to delete corrupt key alias") }        }        val keyGenerator = KeyGenerator.getInstance(            KeyProperties.KEY_ALGORITHM_AES,            ANDROID_KEYSTORE,        )        val spec = KeyGenParameterSpec.Builder(            KEY_ALIAS,            KeyProperties.PURPOSE_ENCRYPT or KeyProperties.PURPOSE_DECRYPT,        )            .setBlockModes(KeyProperties.BLOCK_MODE_GCM)            .setEncryptionPaddings(KeyProperties.ENCRYPTION_PADDING_NONE)            .setKeySize(256)            // Don't require user auth — LMK recovery must work in background.            .setUserAuthenticationRequired(false)            .build()        keyGenerator.init(spec)        return keyGenerator.generateKey()    }    private companion object {        private const val ANDROID_KEYSTORE = "AndroidKeyStore"        private const val KEY_ALIAS = "nous_episodic_memory_v4"        private const val GCM_TRANSFORM = "AES/GCM/NoPadding"        private const val GCM_IV_BYTES = 12        private const val GCM_TAG_BITS = 128    }}
